def _cut(s, n):
    s = s or ""
    return s if len(s) <= n else s[:n].rsplit(" ", 1)[0] + "…"


def _build():  # PROBLEMS from the rows and hard.json; run from the repository root
    hard = json.load(open(DATA["problems"]))
    flags = json.load(open(DATA["flags"]))["sets"]["hard"]["flags"]
    clean = sorted(int(i) for i, f in flags.items() if f["flag"] == "none")
    assert len(clean) == DATA["n"], len(clean)
    rows = {}
    for arm in ARMS:
        rs = [json.loads(line) for line in open(DATA["rows"][arm] + arm + ".jsonl")]
        rows[arm] = {r["problem_index"]: r for r in rs}
        assert len(rs) == DATA["n"] and sorted(rows[arm]) == clean, arm
    out = []
    for i in clean:
        h = hard[i]
        for arm in ARMS:
            r = rows[arm][i]
            assert r["gold"] == h["answer"] and r["unique_id"] == h["unique_id"] and len(r["tail"]) <= DATA["tail"], (arm, i)
            assert not r["cap_hit"] or r["n_new"] == DATA["new"], (arm, i)
        out.append([i, h["source"], _cut(h["problem"], 420), h["answer"]] +
                   [[r["n_new"], int(r["cap_hit"]), r["score_v3"], _cut(r["extracted_v3"], 36), r["tail"]]
                    for r in (rows[arm][i] for arm in ARMS)])
    return out, rows


def _build4(votes):  # FOUR from the four-sample rows; votes=True recomputes the vote (needs math-verify, as the readout did)
    by = {}
    for line in open(DATA["four_samples"]["rows"]):
        r = json.loads(line)
        by.setdefault(r["problem_index"], [None] * 4)[r["sample"]] = r
    assert sorted(by) == [p[0] for p in PROBLEMS] and all(None not in v for v in by.values())
    out = []
    for p in PROBLEMS:
        rs = by[p[0]]
        assert all(r["attempt"] == 0 and r["n_new_16"] == min(r["n_new"], DATA["old"]) for r in rs), p[0]
        if votes:
            from studies.rlneurons.analysis import day1_vote as V  # the readout's vote: plurality, ties to the lower sample
            v16 = V.vote([{**r, "extracted_v3": r["extracted_v3_16"], "score_v3": r["score_v3_16"]} for r in rs])["score"]
            v32 = V.vote(rs)["score"]
        else:
            v16, v32 = None, None
        out.append([v16, v32, [[r["n_new"], int(r["cap_hit"]), r["score_v3"], r["score_v3_16"], _cut(r["extracted_v3"], 36),
                                _cut(r["extracted_v3_16"], 36), int(r["chinese"])] for r in rs]])
    return out, by


# Counts from PROBLEMS, per arm: right and cut off at an allowance, tokens per problem, and the answers past 16,384
def _at(j, cap):
    a = [p[4 + j] for p in PROBLEMS]
    done = [x for x in a if not x[1] and x[0] <= cap]
    return {"right": sum(x[2] for x in done), "cut": len(a) - len(done), "finished": len(done),
            "tokens": round(sum(min(x[0], cap) for x in a) / len(a), 1)}


def _late(j):
    late = [p[4 + j] for p in PROBLEMS if p[4 + j][0] > DATA["old"]]
    return {"n": len(late), "finished": sum(not x[1] for x in late), "right": sum(x[2] for x in late)}


COUNTS = {arm: {"old": _at(j, DATA["old"]), "new": _at(j, DATA["new"]), "late": _late(j)} for j, arm in enumerate(ARMS)}

_S, _Rl, _B = DATA["cells"]["sft_cue"], DATA["cells"]["rl_plain"], DATA["cells"]["base_cue"]
_pct = lambda a, b: f"{100 * a / b:.1f} %"
_n1 = lambda x: f"{x:.1f}".replace("-", "−")
_iv = lambda c: f"95 % interval {_n1(c[0])} to {_n1(c[1])}"
_t = lambda x: f"{round(x):,}"
_sl = _S["of_them_finished"] - _S["of_them_right"]  # sample 1's long answers that end wrong
_lr = lambda c: f"{c['of_them_right']} of {c['answers_longer_than_16384']} ({_pct(c['of_them_right'], c['answers_longer_than_16384'])})"
_gp = lambda g: f"{'+' if g['points'] >= 0 else '−'}{abs(g['points']):.1f} points, {_iv(g['ci95'])}"
_FL, _FR = _F["late"], DATA["four_samples_fresh2026"]
_cut16 = sum(y[3] for f in FOUR for y in f[2] if y[0] > DATA["old"])  # cut-off samples whose text at 16,384 already gives the right answer
_cut16_s1 = sum(f[2][0][3] for f in FOUR if f[2][0][0] > DATA["old"])

